import boto3

client = boto3.client('wafv2')

response = client.create_web_acl(
    Name='MyWAF',
    Scope='REGIONAL',
    DefaultAction={'Allow': {}},
    Rules=[
        {
            'Name': 'BlockIPRule',
            'Priority': 1,
            'Statement': {
                'IPSetReferenceStatement': {
                    'ARN': 'arn:aws:wafv2:us-east-1:123456789012:ipset/example'
                }
            },
            'Action': {'Block': {}},
            'VisibilityConfig': {
                'CloudWatchMetricsEnabled': True,
                'MetricName': 'MyWAFMetric',
                'SampledRequestsEnabled': True
            }
        }
    ],
    VisibilityConfig={
        'CloudWatchMetricsEnabled': True,
        'MetricName': 'MyWAFMetric',
        'SampledRequestsEnabled': True
    }
)

elb_client = boto3.client('elbv2')
elb_response = elb_client.create_load_balancer(
    Name='MyELB',
    Subnets=['subnet-12345678', 'subnet-87654321'],
    SecurityGroups=['sg-12345678'],
    Scheme='internet-facing',
    Type='application'
)

client.associate_web_acl(
    WebACLArn=response['Summary']['ARN'],
    ResourceArn=elb_response['LoadBalancers'][0]['LoadBalancerArn']
)

